4	/// Wraps a `Parser`, parsing each line of a (possibly multiline) span
5	/// independently after trimming its leading/trailing whitespace, then
6	/// stitching the results back together with a single explicit
7	/// [`TokenKind::Newline`] token between lines.
8	///
9	/// This exists for YAML block/folded scalars: their continuation lines
10	/// carry literal indentation (e.g. two leading spaces). Feeding
11	/// that raw text straight to a prose parser makes the newline-plus-
12	/// indentation read as a run of several space characters, which
13	/// incorrectly triggers Harper's "double space" formatting rule.
14	/// De-denting each line before parsing avoids that, without needing to
15	/// understand YAML's specific indentation rules.
16	pub(crate) struct DedentLines<P> {
17	    inner: P,
18	}
19	
20	impl<P: Parser> DedentLines<P> {
21	    pub(crate) fn new(inner: P) -> Self {
22	        Self { inner }
23	    }
24	}
25	
26	impl<P: Parser> Parser for DedentLines<P> {
27	    fn parse(&self, source: &[char]) -> Vec<Token> {
28	        let mut tokens = Vec::new();
29	        let mut chars_traversed = 0;
30	
31	        for line in source.split(|c| *c == '\n') {
32	            if let Some(trimmed) = trim(line) {
33	                let mut new_tokens = self.inner.parse(trimmed.get_content(line));
34	
35	                new_tokens
36	                    .iter_mut()
37	                    .for_each(|t| t.span.push_by(chars_traversed + trimmed.start));
38	
39	                tokens.append(&mut new_tokens);
40	            }
41	
42	            let line_end = chars_traversed + line.len();
43	
44	            if line_end < source.len() {
45	                tokens.push(Token::new(
46	                    Span::new_with_len(line_end, 1),
47	                    TokenKind::Newline(1),
48	                ));
49	            }
50	
51	            chars_traversed += line.len() + 1;
52	        }
53	
54	        tokens
55	    }
56	}
