58	/// The span of `line` with leading/trailing whitespace trimmed, or
59	/// `None` if the line is entirely whitespace.
60	fn trim(line: &[char]) -> Option<Span<char>> {
61	    let start = line.iter().position(|c| !c.is_whitespace())?;
62	    let end = line.len() - line.iter().rev().position(|c| !c.is_whitespace())?;
63	
64	    Some(Span::new(start, end))
65	}
