1	use harper_core::parsers::{LineWise, Parser};
2	use harper_core::{Span, Token};
3	
4	/// Parses each line of a (possibly multiline) span independently after
5	/// trimming its leading/trailing whitespace, then stitches the results
6	/// back together with a single explicit `Newline` token between lines.
7	///
8	/// This exists for YAML block/folded scalars: their continuation lines
9	/// carry literal indentation (e.g. two leading spaces). Feeding
10	/// that raw text straight to a prose parser makes the newline-plus-
11	/// indentation read as a run of several space characters, which
12	/// incorrectly triggers Harper's "double space" formatting rule.
13	/// De-denting each line before parsing avoids that, without needing to
14	/// understand YAML's specific indentation rules.
15	///
16	/// The actual line-splitting/stitching mechanism is shared with other
17	/// per-line parsers (see `harper_core::parsers::LineWise`); this type
18	/// only supplies the YAML-specific "strip" policy (trim whitespace).
19	pub(crate) struct DedentLines<P>(Inner<P>);
20	
21	type StripFn = fn(&[char]) -> Span<char>;
